parameters.jsCode:
// Sanitize and normalize inbound webhook lead payload
const body = $input.item.json.body || $input.item.json;

const fullName = (body.name || body.caller_name || body.full_name || 'Valued Prospect').trim();
const email = (body.email || body.contact_email || '').trim().toLowerCase();
const phone = (body.phone || body.caller_phone || '').trim();
const company = (body.company || body.business_name || 'Independent').trim();
const requirements = (body.requirements || body.message || body.notes || 'Inquiry regarding growth automation').trim();
const budget = (body.budget || body.estimated_budget || 'Unspecified').trim();

// Default booking time slot: next business day at 14:00 UTC if unspecified
let preferredTime = body.preferred_time || body.booking_slot;
let startTime = new Date();
if (preferredTime && !isNaN(Date.parse(preferredTime))) {
  startTime = new Date(preferredTime);
} else {
  startTime.setDate(startTime.getDate() + 1);
  startTime.setUTCHours(14, 0, 0, 0);
}
const endTime = new Date(startTime.getTime() + 45 * 60 * 1000); // 45-min consultation

return {
  json: {
    lead_name: fullName,
    email,
    phone,
    company,
    requirements,
    budget,
    meeting_start_iso: startTime.toISOString(),
    meeting_end_iso: endTime.toISOString(),
    received_at: new Date().toISOString()
  }
};

