parameters.jsCode:
// Parse OpenAI assessment and merge with lead metadata
const rawMessage = $input.item.json.message?.content || '{}';
const intake = $('Normalize & Validate Intake').first().json;

let assessment = {};
try {
  const cleanJson = rawMessage.replace(/```json/g, '').replace(/```/g, '').trim();
  assessment = JSON.parse(cleanJson);
} catch (err) {
  assessment = {
    qualified: true,
    fit_score: 70,
    tier: 'SMB',
    recommended_service: 'General Automation Audit',
    executive_summary: 'Auto-qualified due to parsing fallback.',
    qualification_reasons: ['Valid contact format']
  };
}

return {
  json: {
    ...intake,
    qualified: Boolean(assessment.qualified && assessment.fit_score >= 50),
    fit_score: assessment.fit_score || 50,
    tier: assessment.tier || 'SMB',
    recommended_service: assessment.recommended_service || 'Automation Strategy Audit',
    executive_summary: assessment.executive_summary || 'Prospective growth automation inquiry',
    qualification_reasons: assessment.qualification_reasons || []
  }
};

